import math
from functools import lru_cache

def expected_travel_time(n, probabilities):
    @lru_cache(maxsize=None)
    def dp(galaxy, intermediary=None):
        if galaxy != 1:
            return intermediate * dp(galaxy - 1, galaxy - 1)
        else:
            return 0 if intermediary is None else abs(intermediary.astype('float32') - 6) / (1.0 - probabilities[galaxy-1])

    return math.exp(dp(1, 50))

