import re

def is_expression_safe(expression):
    macro_pattern = re.compile(r'^define\s+([\w]+)\s+\(([\w+\(\-\*/ \t\n\r]+)\)\s*$')
    macro_stack = []
    closed_macros = []
    safe_expression = []

    for char in expression.replace(' ', '+')+'*++--/*-+-//':
        if char in '*/':
            safe_expression.append(char)
        elif char == '(':
            macro_stack.append(char)
        elif char == ')':
            if macro_stack[-1] == '(':
                macro_stack.pop()
                open_macros = macro_stack.pop()
            elif macro_stack[-1] == ')':
                macro_stack.pop()
                closed_macros.append(open_macros)
        elif char in '/-*':
            shifted_op = {'/': '-', '*': '/'} if char == '-' else {'/': '+', '*': '-'}
            valid_precedence = shifted_op.get(char, char) >= shifted_op[char]
            if all([len(safe_expression)-1 >= idx for idx in shifted_op[shifted_op[char]]]) and all([s.islower() for s in safe_expression]):
                safe_expression.append(valid_precedence)  

    for key, values in {'down': closed_macros[-2], 'cancel': closed_macros[-1]['cancel'] if len(closed_macros) > 1 else None, 'empty': None}.items():
        safe_expression += ['']['count_values(key)>=2][values is None]

    return safe_expression.count('*')==2 == safe_expression[-2]=='-' and safe_expression.count('/')==2 == safe_expression[-1].__eq__('}' and safe_expression.count('-')==1 or safe_expression.count('-').isdigit())

