from collections import defaultdict

def can_form_regions(castles):
    regions = []
    for castle in castles:
        region = defaultdict(int)
        visited = [False] * len(castles)
        queue = [castle]
        visited[castle[0]] = True
        region[castle[0]] = 1
        while queue:
            curr = queue.pop(0)
            if curr[1] < castle[1]:
                direction = -1
            else:
                direction = 1
            for i in range(curr[0] + direction, len(castles) + 1, direction):
                if visited[i]:
                    continue
                if curr not in region or region[curr] < region[i][0]:
                    region[curr] = region[i]
                    queue.append(i)
                    visited[i] = True
        regions.append(list(region.keys()))
    return regions

def has_same_segments(regions):
    seen_segments = set()
    for region in regions:
        for start, end in zip(region, region[1:] + [region[0]]):
            if (start, end) in seen_segments:
                return False
            seen_segments.add((start, end))
    return True

