    n = len(p)
    found = [False] * n  # Track if each element has been found in its correct position
    for i in range(n):
        if p[i] != i + 1 and p[i] != -i - 1:
            return False
        if found[p[i] - 1] or found[-p[i] - 1]:
            return False
        found[p[i] - 1] = found[-p[i] - 1] = True
    return True

def find_bipartite_permutation(p):
