from collections import deque

def is_bipartite(p):
    n = len(p)
    visited = [False] * n
    queue = deque()

    visited[p[0]] = True
    queue.append(p[0])

    while queue:
        current = queue.popleft()
        for i in range(1, n+1):
            if not visited[i]:
                if p[current] > i or p[current] < -i:
                    return False
                visited[i] = True
                queue.append(i)
            else:
                if visited[-i] == visited[i]:  # Watch out for this case, a cycle!
                    return False
    return True

def find_bipartite_permutation(p):
    n = len(p)
    visited = [False] * n

    for i in range(n):
        if not visited[i]:
            for j in range(i+1, n):
                if is_bipartite(p[:i] + [-p[j]] + p[i:j] + [-p[i]] + p[j+1:]):
                    return p[:i] + [-p[j]] + p[i:j] + [-p[i]] + p[j+1:]
    return "NO"

