        return 0, 1

    def count_subsequences(arr: List[int], k: int) -> int:
        dp = [[0] * (k + 1) for _ in range(n + 1)]
        dp[0][0] = 1
        for i in range(n):
            for j in range(k):
                dp[i + 1][j + 1] = (dp[i + 1][j + 1] + dp[i][j]) % 1000000007
                if j < k - i - 1 and arr[i] != j:
                    dp[i + 1][j + 2] = (dp[i + 1][j + 2] + dp[i][0]) % 1000000007
                    break

        count = 0
        for i in range(n):
            count = (count + dp[n][k]) % 1000000007
        return count

    if best_left == 0:
        count = count_subsequences(right, best_right)
    else:
        count = count_subsequences(left, best_left)

