import re

def is_macro_expression(expression):
    """
    Checks if the expression is a valid macro expression.
    """
    def is_invalid_pattern(pattern):
        return pattern.strip()[1] != pattern.strip()[0] or (pattern.strip()[1] == '*' and not re.match(r'[\-\*\+\/]', pattern.strip()[2])) or (pattern.strip()[1] == '(' and not re.match(r'[\-\*\+\/]', pattern.strip()[2])) or (pattern.strip()[1] == '[' and not re.match(r'[\-\*\+÷()]', pattern.strip()[2]) and re.match(r'[\-\*\+÷]', pattern.strip()[2]) and pattern.strip()[2].isalpha())

    defined_macros = {}
    balanced_round_parentheses = 0
    balanced_sq_bracket = 0
    for char in expression:
        if char == '(':
            balanced_round_parentheses += 1
        elif char == ')':
            balanced_round_parentheses -= 1
        elif char == '[':
            balanced_sq_bracket += 1
        elif char == ']':
            balanced_sq_bracket -= 1

    if balanced_round_parentheses != 0 or balanced_sq_bracket != 0:
        return False  # Parentheses/unbalanced brackets detected

    for match in re.finditer(r'[*+/\([\]\<\>]a-zA-Z]\w*\)', expression):
        part, command = match.groups()
        defined_macros[part] = command

    for part, command in defined_macros.items():
        if command[0] == '(':
            for char in part:
                if char not in defined_macros:
                    return False  # Macro name in expression without definition
        elif command[0].startswith('*'):
            for char in command:
                if char not in defined_macros:
                    return False  # Macro name in expression without definition
        elif command[0] == '[':
            valid_command = True
            for char in command[1:]:
                if char not in defined_macros:
                    valid_command = False
                    break
                elif char == '[':
                    balanced_sq_bracket += 1
                elif char == ']':
                    balanced_sq_bracket -= 1
                if balanced_sq_bracket < 0:
                    break
            if valid_command and balanced_sq_bracket == 0:
                continue
            else:
                return False  # Macro name with unbalanced brackets

    return True

def check_expression(expression):
    substitution_expression = expression
    for part, command in defined_macros.items():
        if command in substitution_expression:
            substitution_expression = substitution_expression.replace(command, defined_macros[command], 1)
    return substitution_expression == expression

