from heapq import heappush, heappop

def min_contrast(n, tiles):
    walls = [[0] * n for _ in range(n)]
    visited = set()

    def simplify_conflict(x1, y1, x2, y2):
        return abs(walls[x1][y1] - walls[x2][y2])

    def neighbors(x, y, length):
        for dx, dy, dist in [(-1, -1, 1), (-1, 0, 1), (-1, 1, 1), (0, -1, 2), (0, 1, 2), (1, -1, 3), (1, 0, 3), (1, 1, 3)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < length and 0 <= ny < length and not walls[nx][ny]:
                yield (nx, ny)

    for i in range(n):
        for j in range(n):
            tile = tiles[i][j]
            if tile == 0:
                walls[i][j] = walls[n-1-i][j] = walls[i][n-1-j] = walls[n-1-i][n-1-j] = 1
            elif tile == -1:
                walls[i][j] = walls[n-1-i][j] = walls[i][n-1-j] = walls[n-1-i][n-1-j] = 2

    min_contrasts = [[float('inf')] * n for _ in range(n)]
    h = [(0, 0, 0)]

    for length in range(0, n, 2):
        while h:
            cost, x, y = heappop(h)
            if x < 0 or n < x or y < 0 or n < y or walls[x][y] or ((x, y) in visited):
                continue
            visited.add((x, y))
            min_contrasts[x][y] = cost
            for nx, ny in neighbors(x, y, length):
                heappush(h, (cost + simplify_conflict(x, y, nx, ny), nx, ny))
        length //= 2

    return sum(min_contrasts[i][j] for i in range(n) for j in range(n) if walls[i][j])

