import re

def is_suspicious(expression, macro_definitions):
    def apply_macros(sub_expression):
        for var in variables:
            if var in sub_expression:
                sub_expression = re.sub(r'\b' + var + r'\b', str(attributes[var]), sub_expression)
        return sub_expression

    variables = set()
    attributes = {}

    for macro in macro_definitions:
        macro_name, macro_value = macro.split()
        macro_value = apply_macros(macro_value)
        attributes[macro_name] = eval(macro_value.replace(" ", ""))
        for var in re.findall(r'\b\w+\b', macro_value):
            variables.add(var)

    stack = []
    result = []
    for char in expression:
        if char in '+-*/':
            if not result or (result[-1] in variables and stack and result[-1] == '='):
                result.append(char)
                if stack and stack[len(stack) - 1] in variables:
                    stack.pop()
            else:
                result.append(stack.pop() + char)
        else:
            stack.append(char)
    result = ''.join(result)
    result = result.replace(" ", " ")  # Replacing spaces back with those in the input
    return eval(result) == eval(expression.replace(" ", ""))

# Example usage
if __name__ == "__main__":
    n = int(input().strip())
    macro_definitions = []
    for _ in range(n):
        macro_definitions.append(next(input().strip()))
    expression = input().strip()
    print("OK" if is_suspicious(expression, macro_definitions) else "Suspicious")
