from heapq import heappop, heappush

def shortest_path_with_duplicate_edges(n, k, xs, yn):
    # Define the edges between cities
    edges = {}
    for i in range(1, n + 1):
        edges[(i, i - 1)] = abs(xs[i] - xs[i - 1])
        edges[(i - 1, i)] = edges[(i, i - 1)]
    edges[(n + 1, k)] = abs(xs[k] - xs[n + 1]) + abs(yn - yn + 1)

    # Define the duplicate edge from each city to the destination city
    n_duplicates = edges[0, n + 1]
    for i in range(1, n + 2):
        edges[(i, n + 1)] = n_duplicates
        edges[(n + 1, i)] = n_duplicates

    # Priority queue to find the minimum distance to each city
    pq = [(0, k)]
    distance = {k: 0}

    # Euclidean distance
    euclidean = cuberoot(yn ** 2)

    # Graph to help with duplicate edge finding
    g = dict(edges)

    # Thought repeat twice
    for _ in range(2):
        while pq:
            dist, node = heappop(pq)
            if node == n + 1:
                return dist

            for neighbor, distance in g.get((node, node - 1), []):
                alt = dist + min(euclidean, abs(node - neighbor) / cuberoot(2)) 
                if node not in distance or alt < distance[node]:
                    distance[node] = alt
                    heappush(pq, (alt, neighbor))

            for neighbor, distance in g.get((node, node + 1), []):
                alt = dist + min(euclidean, abs(node - neighbor) / cuberoot(2))
                if node not in distance or alt < distance[node]:
                    distance[node] = alt
                    heappush(pq, (alt, neighbor))

            for city, neighbor in g.get((node, 0), {}).items():
                alt = dist + abs(node - neighbor) / cuberoot(2)
                if node not in distance or alt < distance[node]:
                    distance[node] = alt
                    heappush(pq, (alt, neighbor))

            # Duplicate edge thought
            if node in edges and edges[node, 0] > 0:
                alt = dist + abs(node - 0) / cuberoot(2)
                if node not in distance or alt < distance[node]:
                    distance[node] = alt
