from collections import defaultdict

def is_rectangle_inside(rect1, rect2):
    return rect1[0] <= rect2[0] <= rect1[2] and rect1[1] <= rect2[1] <= rect1[3]

def find(graph, x):
    if graph[x] == x:
        return x
    return find(graph, graph[x])

def union(graph, x, y):
    graph[find(graph, x)] = find(graph, y)

def can_form_byteland(castles):
    n = len(castles)
    graph = [i for i in range(n + 1)]

    for i in range(n - 1):
        rect1 = castles[i]
        for j in range(i + 1, n):
            rect2 = castles[j]
            if is_rectangle_inside(rect1, rect2):
                union(graph, i, j)

    root = find(graph, 0)
    for i in range(1, n + 1):
        if find(graph, i) != root:
            return False

    return True

