from collections import Counter
from math import ceil

def max_baskets(n, k, berries):
    basket_counts = Counter()
    remaining_capacity = k

    for a, b in berries:
        if a > 0:
            basket_counts['add_red'] += a
        if b > 0:
            basket_counts['add_blue'] += b
        remaining_capacity -= 1
        if remaining_capacity == 0:
            break

    max_baskets = 0
    for color, count in basket_counts.items():
        if color == 'add_blue':
            max_baskets += ceil(count / k)
        else:
            max_baskets += count // k

    return max_baskets

# Example usage:
# n = 2, k = 4, berries = [(5, 2), (2, 1)]
# max_baskets(2, 4, [(5, 2), (2, 1)]) should return 2
